import { signal } from 'kerfjs';
import { delegate } from 'kerfjs';
import type { SafeHtml } from 'kerfjs';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { PageHeader } from '@kerfjs/ui/page-header';
import { ResizableRegion } from '@kerfjs/ui/resizable-region';
import { wireResizableRegions } from '@kerfjs/ui/wire-resizable-regions';
import { ValueTable } from '@kerfjs/ui/value-table';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import './shell.css';

type Pane = 'navigation' | 'workspace' | 'inspector';
interface Preferences { inspectorWidth: number; selected: string }
interface ShellOptions {
  id: string;
  load(): Partial<Preferences>;
  save(value: Preferences): void;
  newTask(): void;
}
// The host renders SafeHtml synchronously into the stable root (using its Kerf renderer).
export function createShell(root: HTMLElement, paint: (html: SafeHtml) => void, options: ShellOptions) {
  const saved = options.load();
  const width = signal(Math.max(200, Math.min(360, Number.isFinite(saved.inspectorWidth) ? saved.inspectorWidth! : 260)));
  const selected = signal(saved.selected === 'projects' ? 'projects' : 'inbox');
  const phonePane = signal<Pane>('workspace');
  const narrow = matchMedia('(max-width: 48rem)');
  const inspectorId = options.id + '-inspector';
  const persist = () => options.save({ inspectorWidth: width.value, selected: selected.value });
  const renderInspector = () => <aside class="shell__pane" aria-label="Inspector">
    <Toolbar label="Inspector" leading={<ToolbarText text="Inspector" />} />
    <div class="kui-scroll-owner kui-pane-body" tabindex="0" aria-label="Inspector details">
      <ValueTable label="Selected workspace"><div><dt>Section</dt><dd>{selected.value === 'inbox' ? 'Inbox' : 'Projects'}</dd></div><div><dt>Status</dt><dd>Ready for review</dd></div></ValueTable>
    </div>
  </aside>;
  const render = () => <section class="shell kui-layout" data-phone-pane={phonePane.value}>
    <Toolbar label="Workspace toolbar" leading={<ToolbarText text="Atlas" />} trailing={
      <ToolbarControlGroup appearance="borderless" label="Show pane">
        <button type="button" data-action="shell-pane" data-pane="navigation" aria-controls={options.id + '-navigation'} aria-pressed={String(phonePane.value === 'navigation')}>Navigation</button>
        <button type="button" data-action="shell-pane" data-pane="workspace" aria-controls={options.id + '-workspace'} aria-pressed={String(phonePane.value === 'workspace')}>Workspace</button>
        <button type="button" data-action="shell-pane" data-pane="inspector" aria-controls={inspectorId} aria-pressed={String(phonePane.value === 'inspector')}>Inspector</button>
      </ToolbarControlGroup>} />
    <div class="shell__body">
      <aside id={options.id + '-navigation'} class="shell__navigation shell__pane" hidden={narrow.matches && phonePane.value !== 'navigation'}>
        <nav class="kui-sidebar kui-scroll-owner" aria-label="Workspace navigation" tabindex="0">
          <section class="kui-sidebar-section"><MenuHeader label="Workspace" />
            <MenuItem action="shell-navigate" itemId="inbox" label="Inbox" selected={selected.value === 'inbox'} />
            <MenuItem action="shell-navigate" itemId="projects" label="Projects" selected={selected.value === 'projects'} />
          </section>
          <section class="kui-sidebar-section"><MenuHeader label="Resources" /><div class="kui-sidebar-surface"><strong>Team workspace</strong><p>Shared planning and delivery.</p></div></section>
        </nav>
      </aside>
      <main id={options.id + '-workspace'} class="shell__main shell__pane" hidden={narrow.matches && phonePane.value !== 'workspace'}>
        <PageHeader title={selected.value === 'inbox' ? 'Inbox' : 'Projects'} action={<button class="shell__button" type="button" data-action="shell-new">New task</button>} />
        <div class="kui-scroll-owner kui-pane-body kui-section-stack" tabindex="0" aria-label="Workspace content">
          {['Review release plan', 'Prepare navigation audit', 'Confirm milestones'].map(title => <article class="shell__card kui-surface-body"><h2>{title}</h2><p>Ready for the next team review.</p></article>)}
        </div>
      </main>
      <div class="shell__inspector" hidden={narrow.matches && phonePane.value !== 'inspector'}>
        {narrow.matches ? <div id={inspectorId} class="shell__pane">{renderInspector()}</div> :
          <ResizableRegion id={inspectorId} label="Inspector width" size={width.value} min={200} max={360} edge="start">{renderInspector()}</ResizableRegion>}
      </div>
    </div>
  </section>;
  const draw = () => paint(render());
  const offActions = delegate(root, 'click', '[data-action]', (_event, element) => {
    switch (element.dataset.action) {
      case 'shell-pane': {
        const pane = element.dataset.pane as Pane;
        if (!['navigation', 'workspace', 'inspector'].includes(pane)) return;
        phonePane.value = pane; draw();
        if (narrow.matches) root.querySelector<HTMLElement>('#' + CSS.escape(options.id + '-' + pane) + ' .kui-scroll-owner')?.focus();
        break;
      }
      case 'shell-navigate':
        if (element.dataset.itemId !== 'inbox' && element.dataset.itemId !== 'projects') return;
        selected.value = element.dataset.itemId; phonePane.value = 'workspace'; persist(); draw();
        if (narrow.matches) root.querySelector<HTMLElement>('.shell__main .kui-scroll-owner')?.focus();
        break;
      case 'shell-new': options.newTask(); break;
    }
  });
  const offResize = wireResizableRegions(root, {
    onResize: ({ id, size }) => {
      if (id !== inspectorId) return;
      width.value = size;
      draw();
      persist();
    }
  });
  const onViewport = () => {
    const focused = root.contains(document.activeElement);
    draw();
    if (focused && narrow.matches) root.querySelector<HTMLElement>('.shell__main:not([hidden]) .kui-scroll-owner, .shell__navigation:not([hidden]) .kui-scroll-owner, .shell__inspector:not([hidden]) .kui-scroll-owner')?.focus();
  };
  narrow.addEventListener('change', onViewport);
  draw();
  return () => { offActions(); offResize(); narrow.removeEventListener('change', onViewport); };
}

