.shell { height: 100dvh; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); overflow: hidden; color: var(--kui-color-text); background: var(--kui-color-surface); }
.shell__body { display: flex; min-width: 0; min-height: 0; }
.shell__pane { display: grid; grid-template-rows: auto minmax(0, 1fr); height: 100%; min-width: 0; min-height: 0; }
.shell__navigation { flex: 0 0 13rem; grid-template-rows: minmax(0, 1fr); }
.shell__main { flex: 1; }
.shell__inspector { min-height: 0; flex: none; }
.shell [hidden] { display: none; }
.shell .kui-scroll-owner { overscroll-behavior: contain; }
.shell__card { border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); overflow-wrap: anywhere; }
.shell__card h2 { margin: 0; font-size: var(--kui-font-l); }
.shell__button { min-height: 2.5rem; padding: var(--kui-space-xs) var(--kui-space-s); background: var(--kui-color-surface); color: var(--kui-color-text); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); font: inherit; }
.shell__button:focus-visible, .shell .kui-scroll-owner:focus-visible { outline: var(--kui-focus-ring); outline-offset: -2px; }
@media (max-width: 48rem) { .shell__body { display: block; } .shell__navigation, .shell__main, .shell__inspector { width: 100%; height: 100%; } .shell .kui-toolbar { height: auto; min-height: 3rem; flex-wrap: wrap; } }
